import Foundation
import SwiftData

/// Built-in calibre catalogue, loaded from Calibers.json (generated by tools/generate_assets.py).
/// Seeded once into SwiftData so users can rename, archive or add their own.
enum CaliberCatalog {
    enum Category: String, CaseIterable {
        case rimfire = "Randfeuer"
        case handgun = "Kurzwaffe"
        case rifle = "Langwaffe"
        case blackPowder = "Schwarzpulver"
        case shotgun = "Flinte"
        case air = "Luftdruck"
        case other = "Andere"
    }

    struct Outline: Decodable {
        let width: Double
        let height: Double
        let `case`: String?
        let head: String?
        let bullet: String?
        /// Paper band drawn over the bullet (paper-patched GP 1890 bullet); nil for jacketed bullets.
        let patch: String?
        /// Bare lead tip of a soft point, drawn over the bullet.
        let tip: String?
        /// "polymer" for a plastic tip; nil for bare lead.
        let tipMaterial: String?
        /// "steel" for the steel head of a hybrid case (.277 SIG Fury); nil for brass.
        let headMaterial: String?
        /// "steel" for a steel-capped nose, "lead" for a bare lead bullet; nil means a copper-coloured jacket.
        let bulletMaterial: String?
        /// "copper", "steel" (lacquered), "nickel", "paper" or "hybrid" (brass body, steel head) where the case is not brass.
        let caseMaterial: String?
    }

    struct Item: Decodable, Identifiable {
        let id: String
        let name: String
        let category: String
        let aliases: [String]
        /// Printable alternative names, e.g. "9 mm Luger" for 9x19 mm.
        let displayAliases: [String]?
        let kind: String
        /// Shared by cartridges with identical measurements (e.g. .308 Win / 7.62 NATO); nil when alone.
        let dimensionGroup: String?
        let outline: Outline
    }

    private struct File: Decodable { let calibers: [Item] }

    static let items: [Item] = {
        guard let url = Bundle.main.url(forResource: "Calibers", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let file = try? JSONDecoder().decode(File.self, from: data) else { return [] }
        return file.calibers
    }()

    private static let byID = Dictionary(items.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })

    static func item(id: String) -> Item? { byID[id] }

    /// Finds a catalogue entry for free text like "GP90", "9mm", "45 Auto" or ".22 lr".
    static func match(_ text: String) -> Item? {
        let key = normalizedAlias(text)
        guard !key.isEmpty else { return nil }
        return exactMatch(text) ?? items.first { normalizedAlias($0.name).hasPrefix(key) }
    }

    /// The catalogue entry whose name or one of its other names is `text`, spelled any way.
    /// Names win over other names: ".32 S&W" is that calibre, not the .32 S&W Long ("32s&w").
    static func exactMatch(_ text: String) -> Item? {
        let key = normalizedAlias(text)
        guard !key.isEmpty else { return nil }
        return items.first { normalizedAlias($0.name) == key } ?? items.first {
            $0.aliases.contains { normalizedAlias($0) == key }
                || ($0.displayAliases ?? []).contains { normalizedAlias($0) == key }
        }
    }

    static func normalizedAlias(_ s: String) -> String {
        s.lowercased()
            .replacingOccurrences(of: "×", with: "x")
            .replacingOccurrences(of: ",", with: ".")
            .filter { !$0.isWhitespace }
            .replacingOccurrences(of: "mm", with: "")
            .trimmingCharacters(in: CharacterSet(charactersIn: "."))
    }

    /// Ids of the catalogue calibres this journal has already been given.
    static let seededIDsKey = "caliberCatalogSeededIDs"

    /// Inserts each catalogue calibre once, also those the catalogue gains in a later version.
    /// A calibre the user made by hand under one of its names is linked to it instead.
    /// A screenshot run seeds its in-memory store every time: the ids it would leave in the
    /// simulator's defaults must not decide what the next run shows.
    @MainActor
    static func seedIfNeeded(_ context: ModelContext, always: Bool = ScreenshotData.isActive) {
        let seeded = always ? [] : Set(UserDefaults.standard.stringArray(forKey: seededIDsKey) ?? [])
        let new = items.filter { !seeded.contains($0.id) }
        guard !new.isEmpty else { return }
        let existing = (try? context.fetch(FetchDescriptor<Caliber>())) ?? []
        let linked = Dictionary(existing.map { ($0.catalogID, $0) }, uniquingKeysWith: { a, _ in a })
        // The user's own calibres (e.g. ".32 S&W Long WC" made by hand) by the catalogue entry they name.
        var own: [String: Caliber] = [:]
        for c in existing where c.catalogID.isEmpty {
            if let id = exactMatch(c.name)?.id, own[id] == nil { own[id] = c }
        }
        for item in new {
            if let c = linked[item.id] ?? own[item.id] {
                c.catalogID = item.id
                if c.category.isEmpty { c.category = item.category }
            } else {
                let c = Caliber(name: item.name, category: item.category)
                c.catalogID = item.id
                context.insert(c)
            }
        }
        try? context.save()
        if !always { UserDefaults.standard.set(items.map(\.id), forKey: seededIDsKey) }
    }

    /// With iCloud sync every device seeds the catalogue once, so the same calibre can
    /// arrive twice. Merge duplicates (same catalogue id) into the oldest record.
    /// Returns the number of records merged away.
    @MainActor
    @discardableResult
    static func deduplicate(_ context: ModelContext) -> Int {
        guard let all = try? context.fetch(FetchDescriptor<Caliber>(sortBy: [SortDescriptor(\.createdAt)])) else { return 0 }
        var keeper: [String: Caliber] = [:]
        var merged = 0
        for c in all where !c.catalogID.isEmpty {
            guard let keep = keeper[c.catalogID] else { keeper[c.catalogID] = c; continue }
            // A freshly seeded duplicate carries no intent of the user, so the oldest record keeps
            // its archived state. Only a duplicate that is actually in use brings the calibre back.
            let inUse = !(c.barrels ?? []).isEmpty || !(c.ammunitions ?? []).isEmpty || !(c.entries ?? []).isEmpty
            for b in c.barrels ?? [] {
                var list = (b.calibers ?? []).filter { $0 != c }
                if !list.contains(keep) { list.append(keep) }
                b.calibers = list
            }
            for a in c.ammunitions ?? [] { a.caliber = keep }
            for e in c.entries ?? [] { e.caliber = keep }
            if inUse, !c.isArchived { keep.isArchived = false }
            context.delete(c)
            merged += 1
        }
        if merged > 0 { try? context.save() }
        return merged
    }
}
